"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, useId, useState } from "react";

import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { GlobeIcon } from "../parts/icons";
import { AgendaList } from "./week-calendar/agenda-list";
import { AllDayRow } from "./week-calendar/all-day-row";
import { CALENDARS, FIRST_HOUR, LAST_HOUR, SAMPLE_ALL_DAY, SAMPLE_EVENTS, type TimedEvent, TODAY } from "./week-calendar/data";
import { dayOfMonth, mondayOf, shortDate, weekdayName } from "./week-calendar/layout";
import { QuickCreate } from "./week-calendar/quick-create";
import { type Draft, TimeGrid } from "./week-calendar/time-grid";
import { type CalendarView, Toolbar } from "./week-calendar/toolbar";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

const LENGTH = { week: 7, work: 5, day: 1, agenda: 7 } satisfies Record<CalendarView, number>;

/** The first free hour on a day at or after 9 AM, for a drafted event. */
function nextFreeHour(events: TimedEvent[], day: number) {
  for (let hour = Math.max(9, FIRST_HOUR); hour < LAST_HOUR; hour += 1) {
    const start = hour * 60;
    if (!events.some((event) => event.day === day && event.start < start + 60 && event.end > start)) return start;
  }
  return 9 * 60;
}

/**
 * A clinic calendar for a week, a work week, a day or an agenda. Draw an event
 * by dragging on the grid, move or stretch one by dragging it, and hide whole
 * calendars from the menu. On the grid, left and right pick a day and carry
 * into the next range, T goes to today, and N drafts an event at the next free
 * hour.
 */
export function WeekCalendar({ className }: { className?: string }) {
  const [events, setEvents] = useState(SAMPLE_EVENTS);
  const [view, setView] = useState<CalendarView>("week");
  const [anchor, setAnchor] = useState(TODAY);
  const [direction, setDirection] = useState(1);
  const [hidden, setHidden] = useState<Set<string>>(() => new Set());
  const [draft, setDraft] = useState<Draft | null>(null);
  const [creating, setCreating] = useState(false);
  const [announce, setAnnounce] = useState("");
  const reduceMotion = useReducedMotion();
  const titleId = useId();

  const length = LENGTH[view];
  const start = view === "day" ? anchor : mondayOf(anchor);
  const days = Array.from({ length }, (_, index) => start + index);
  const visible = events.filter((event) => !hidden.has(event.calendar));
  const allDay = SAMPLE_ALL_DAY.filter((event) => !hidden.has(event.calendar));
  const last = days[days.length - 1] ?? start;
  const rangeLabel = length === 1 ? `${weekdayName(start)}, ${shortDate(start)}` : `${shortDate(start)} to ${shortDate(last)}, 2026`;

  const goTo = (next: number) => {
    setDirection(next >= anchor ? 1 : -1);
    setAnchor(next);
  };

  const step = (sign: -1 | 1) => goTo(anchor + sign * (view === "day" ? 1 : 7));

  const draftAt = (day: number) => {
    const at = nextFreeHour(visible, day);
    setDraft({ day, start: at, end: at + 45 });
    setCreating(true);
  };

  const onGridKey = (event: KeyboardEvent) => {
    if (event.target !== event.currentTarget) return;
    if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
      event.preventDefault();
      let next = anchor + (event.key === "ArrowRight" ? 1 : -1);
      // The work week skips the weekend.
      if (view === "work") while (((next % 7) + 7) % 7 > 4) next += event.key === "ArrowRight" ? 1 : -1;
      goTo(next);
    } else if (event.key === "t" || event.key === "T") {
      goTo(TODAY);
    } else if (event.key === "n" || event.key === "N") {
      event.preventDefault();
      draftAt(anchor);
    }
  };

  const save = (title: string, calendar: string) => {
    if (!draft) return;
    setEvents((current) => [...current, { id: `new-${Date.now()}`, title, calendar, ...draft }]);
    setHidden((current) => {
      const next = new Set(current);
      next.delete(calendar);
      return next;
    });
    setAnnounce(`Added ${title}.`);
    setDraft(null);
    setCreating(false);
  };

  const cancel = () => {
    setDraft(null);
    setCreating(false);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 px-5 pt-4">
        <h2 id={titleId} className="text-base font-semibold">
          Harbour Street clinic
        </h2>
        <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
          <GlobeIcon aria-hidden="true" className="size-3.5" />
          London time
        </span>
      </header>
      <Toolbar
        rangeLabel={rangeLabel}
        view={view}
        onView={setView}
        onStep={step}
        onToday={() => goTo(TODAY)}
        onAdd={() => draftAt(anchor)}
        calendars={CALENDARS}
        hidden={hidden}
        onToggleCalendar={(id) =>
          setHidden((current) => {
            const next = new Set(current);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
          })
        }
      />
      {creating && draft ? <QuickCreate draft={draft} calendars={CALENDARS} onSave={save} onCancel={cancel} /> : null}
      <p className="sr-only" aria-live="polite">
        {announce}
      </p>

      <div className="relative overflow-hidden">
        <AnimatePresence mode="popLayout" initial={false} custom={direction}>
          <motion.div
            key={`${view}-${start}`}
            initial={reduceMotion ? { opacity: 0 } : { x: `${direction * 12}%`, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={reduceMotion ? { opacity: 0 } : { x: `${direction * -12}%`, opacity: 0 }}
            transition={reduceMotion ? { duration: 0.12 } : { type: "spring", stiffness: 300, damping: 35 }}
          >
            {view === "agenda" ? (
              <AgendaList days={days} events={visible} calendars={CALENDARS} />
            ) : (
              <div
                tabIndex={0}
                onKeyDown={onGridKey}
                aria-label={`Calendar grid, ${rangeLabel}. Left and right pick a day, T goes to today, N drafts an event.`}
                className="scroll-fade-effect-y scrollbar-none max-h-[32rem] overflow-auto outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset"
              >
                <div className={cn(length > 1 && "min-w-[40rem]")}>
                <div className="sticky top-0 z-20 border-b border-border bg-card">
                  <div className="flex">
                    <span className="w-14 shrink-0" />
                    <div className="grid-cols-(--cols) grid flex-1" style={
                      // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
                      { "--cols": `repeat(${days.length}, minmax(0, 1fr))` } as VarStyle
                    }>
                      {days.map((day) => (
                        <div key={day} className="flex flex-col items-center gap-0.5 py-2 text-xs">
                          <span className={cn(day === anchor ? "text-foreground" : "text-muted-foreground")}>{weekdayName(day)}</span>
                          <span
                            className={cn(
                              "grid size-7 place-items-center rounded-full text-sm font-semibold tabular-nums",
                              day === TODAY ? "bg-primary text-primary-foreground" : day === anchor ? "border border-foreground" : "",
                            )}
                          >
                            {dayOfMonth(day)}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                  <AllDayRow days={days} events={allDay} calendars={CALENDARS} />
                </div>
                <TimeGrid
                  days={days}
                  events={visible}
                  calendars={CALENDARS}
                  selectedDay={anchor}
                  draft={draft}
                  onChange={(id, next) => setEvents((current) => current.map((item) => (item.id === id ? { ...item, ...next } : item)))}
                  onDraft={(next, done) => {
                    setDraft(next);
                    if (done) setCreating(true);
                  }}
                />
                </div>
              </div>
            )}
          </motion.div>
        </AnimatePresence>
      </div>
    </BlockFrame>
  );
}

