/** The range as a list: each day with its events in time order, and a line for a free day. */
export function AgendaList({ days, events, calendars }: AgendaListProps) {
  return (
    <ol aria-label="Agenda" className="flex flex-col">
      {days.map((day) => {
        const today = events.filter((event) => event.day === day).sort((a, b) => a.start - b.start);
        return (
          <li key={day} className="grid gap-2 px-5 py-3 @md:grid-cols-[10rem_1fr]">
            <h3 className="text-sm font-medium">{longDate(day)}</h3>
            {today.length === 0 ? (
              <p className="text-sm text-muted-foreground">Nothing booked</p>
            ) : (
              <ul className="flex flex-col gap-1.5">
                {today.map((event) => {
                  const calendar = calendars.find((item) => item.id === event.calendar) ?? calendars[0]!;
                  return (
                    <li key={event.id} className="flex items-center gap-3 text-sm">
                      <span aria-hidden="true" className={cn("size-2 shrink-0 rounded-full", HUE_FILL[calendar.hue])} />
                      <span className="w-36 shrink-0 tabular-nums text-muted-foreground">
                        {clock(event.start)} to {clock(event.end)}
                      </span>
                      <span className="min-w-0 truncate">{event.title}</span>
                    </li>
                  );
                })}
              </ul>
            )}
          </li>
        );
      })}
    </ol>
  );
}

