/**
 * The all-day strip: each event is one bar across the days it covers, clipped
 * to the range on screen. Bars that would collide stack on separate rows.
 */
export function AllDayRow({ days, events, calendars }: AllDayRowProps) {
  const first = days[0] ?? 0;
  const last = days[days.length - 1] ?? 0;
  const inRange = events.filter((event) => event.lastDay >= first && event.firstDay <= last);
  const rows: AllDayEvent[][] = [];
  for (const event of [...inRange].sort((a, b) => a.firstDay - b.firstDay)) {
    const row = rows.find((items) => items.every((item) => item.lastDay < event.firstDay || item.firstDay > event.lastDay));
    if (row) row.push(event);
    else rows.push([event]);
  }

  return (
    <div className="flex border-b border-border">
      <span className="w-14 shrink-0 py-1.5 pr-2 text-right text-xs text-muted-foreground">All day</span>
      <ul
        aria-label="All-day events"
        className="grid-cols-(--cols) grid min-h-8 flex-1 gap-y-1 py-1"
        style={
          // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
          { "--cols": `repeat(${days.length}, minmax(0, 1fr))` } as VarStyle
        }
      >
        {rows.flatMap((row, rowIndex) =>
          row.map((event) => {
            const calendar = calendars.find((item) => item.id === event.calendar) ?? calendars[0]!;
            const from = Math.max(event.firstDay, first) - first;
            const to = Math.min(event.lastDay, last) - first;
            return (
              <li
                key={event.id}
                className={cn("col-(--col) row-(--row) relative isolate mx-0.5 truncate rounded-md border-l-2 px-1.5 py-0.5 text-xs font-medium", HUE_BORDER[calendar.hue])}
                style={
                  // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
                  { "--col": `${from + 1} / ${to + 2}`, "--row": String(rowIndex + 1) } as VarStyle
                }
              >
                <span aria-hidden="true" className={cn("absolute inset-0 -z-10 rounded-r-md opacity-20", HUE_FILL[calendar.hue])} />
                {event.title}
                <span className="sr-only">
                  , {shortDate(event.firstDay)} to {shortDate(event.lastDay)}
                </span>
              </li>
            );
          }),
        )}
      </ul>
    </div>
  );
}

