"use client";

import { type KeyboardEvent, useRef } from "react";

const NEXT = new Set(["ArrowRight", "ArrowDown"]);
const PREVIOUS = new Set(["ArrowLeft", "ArrowUp"]);

/**
 * Arrow-key movement for a radio group of `count` items. Tab reaches the
 * selected item only; arrows, Home and End move focus and select, as a radio
 * group does. Spread `itemProps(index)` on each item.
 */
export function useRoving(count: number, selected: number, onSelect: (index: number) => void) {
  const items = useRef<(HTMLElement | null)[]>([]);

  const onKeyDown = (event: KeyboardEvent) => {
    let next: number;
    if (NEXT.has(event.key)) next = (selected + 1) % count;
    else if (PREVIOUS.has(event.key)) next = (selected - 1 + count) % count;
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = count - 1;
    else return;
    event.preventDefault();
    onSelect(next);
    items.current[next]?.focus();
  };

  const itemProps = (index: number) => ({
    ref: (node: HTMLElement | null) => {
      items.current[index] = node;
    },
    tabIndex: index === selected ? 0 : -1,
    onKeyDown,
  });

  return { itemProps };
}

