import { type PointerEvent, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

import { HUE_BORDER } from "../shared/people";
import { type CalendarSource, FIRST_HOUR, LAST_HOUR, SNAP, type TimedEvent, TODAY } from "./data";
import { EventBlock } from "./event-block";
import { clock, longDate, placeDay, snap } from "./layout";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

const SPAN = (LAST_HOUR - FIRST_HOUR) * 60;
const HOURS = Array.from({ length: LAST_HOUR - FIRST_HOUR }, (_, index) => FIRST_HOUR + index);
const hourLabel = (hour: number) => (hour === 12 ? "12 pm" : hour > 12 ? `${hour - 12} pm` : `${hour} am`);
// Sample "now": 10:40 AM on the sample today.
const NOW = 640;

/** A new event being drawn, before it has a title. */
export interface Draft {
  day: number;
  start: number;
  end: number;
}

/** Props for the hour grid of one or more days. */
export interface TimeGridProps {
  days: number[];
  events: TimedEvent[];
  calendars: CalendarSource[];
  selectedDay: number;
  draft: Draft | null;
  onChange: (id: string, next: Pick<TimedEvent, "day" | "start" | "end">) => void;
  onDraft: (draft: Draft, done: boolean) => void;
}

type Drag =
  | { mode: "move" | "resize"; origin: TimedEvent; x: number; y: number }
  | { mode: "create"; day: number; anchor: number };

/**
 * The hour grid: one column per day, events placed side by side where they
 * overlap, a line at the current time, and a tint on the selected day. Drag on
 * an empty stretch to draw a new event; drag an event to move it, or its foot
 * to change its length. Every change snaps to a quarter hour.
 */
export function TimeGrid({ days, events, calendars, selectedDay, draft, onChange, onDraft }: TimeGridProps) {
  const areaRef = useRef<HTMLDivElement>(null);
  const [drag, setDrag] = useState<Drag | null>(null);
  const helpId = useId();

  const minutesAt = (clientY: number) => {
    const rect = areaRef.current?.getBoundingClientRect();
    if (!rect) return FIRST_HOUR * 60;
    return FIRST_HOUR * 60 + ((clientY - rect.top) / rect.height) * SPAN;
  };

  const capture = (pointer: PointerEvent) => {
    areaRef.current?.setPointerCapture(pointer.pointerId);
  };

  const startCreate = (pointer: PointerEvent, day: number) => {
    if (pointer.button !== 0) return;
    const anchor = Math.max(FIRST_HOUR * 60, Math.min(LAST_HOUR * 60 - SNAP, snap(minutesAt(pointer.clientY) - SNAP / 2, SNAP)));
    capture(pointer);
    setDrag({ mode: "create", day, anchor });
    onDraft({ day, start: anchor, end: anchor + 30 }, false);
  };

  const startEvent = (pointer: PointerEvent, origin: TimedEvent, mode: "move" | "resize") => {
    if (pointer.button !== 0) return;
    pointer.stopPropagation();
    capture(pointer);
    setDrag({ mode, origin, x: pointer.clientX, y: pointer.clientY });
  };

  const onPointerMove = (pointer: PointerEvent) => {
    if (!drag) return;
    const rect = areaRef.current?.getBoundingClientRect();
    if (!rect) return;
    if (drag.mode === "create") {
      const at = snap(minutesAt(pointer.clientY), SNAP);
      const start = Math.min(drag.anchor, at);
      const end = Math.max(drag.anchor + SNAP, at);
      onDraft({ day: drag.day, start, end: Math.min(end, LAST_HOUR * 60) }, false);
      return;
    }
    const { origin } = drag;
    const minutes = snap(((pointer.clientY - drag.y) / rect.height) * SPAN, SNAP);
    if (drag.mode === "resize") {
      onChange(origin.id, { day: origin.day, start: origin.start, end: Math.max(origin.start + SNAP, Math.min(LAST_HOUR * 60, origin.end + minutes)) });
      return;
    }
    const length = origin.end - origin.start;
    const shiftDays = Math.round((pointer.clientX - drag.x) / (rect.width / days.length));
    const index = Math.max(0, Math.min(days.length - 1, days.indexOf(origin.day) + shiftDays));
    const start = Math.max(FIRST_HOUR * 60, Math.min(LAST_HOUR * 60 - length, origin.start + minutes));
    onChange(origin.id, { day: days[index] ?? origin.day, start, end: start + length });
  };

  const onPointerUp = () => {
    if (drag?.mode === "create" && draft) onDraft(draft, true);
    setDrag(null);
  };

  const nudge = (event: TimedEvent, shiftDays: number, minutes: number, resize: boolean) => {
    if (resize) {
      onChange(event.id, { day: event.day, start: event.start, end: Math.max(event.start + SNAP, Math.min(LAST_HOUR * 60, event.end + minutes)) });
      return;
    }
    const length = event.end - event.start;
    const start = Math.max(FIRST_HOUR * 60, Math.min(LAST_HOUR * 60 - length, event.start + minutes));
    onChange(event.id, { day: event.day + shiftDays, start, end: start + length });
  };

  const draggingId = drag && drag.mode !== "create" ? drag.origin.id : null;

  return (
    <div className="flex">
      <p id={helpId} className="sr-only">
        Alt with an arrow key moves the event. Shift, Alt and up or down changes its length.
      </p>
      <div aria-hidden="true" className="relative w-14 shrink-0">
        {HOURS.map((hour) => (
          <span
            key={hour}
            className="top-(--top) absolute right-2 -translate-y-1/2 whitespace-nowrap text-xs tabular-nums text-muted-foreground"
            style={
              // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
              { "--top": `${((hour - FIRST_HOUR) / (LAST_HOUR - FIRST_HOUR)) * 100}%` } as VarStyle
            }
          >
            {hour === FIRST_HOUR ? "" : hourLabel(hour)}
          </span>
        ))}
      </div>
      <div
        ref={areaRef}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        className="grid-cols-(--cols) relative grid h-168 flex-1 select-none"
        style={
          // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
          { "--cols": `repeat(${days.length}, minmax(0, 1fr))` } as VarStyle
        }
      >
        {HOURS.map((hour) => (
          <span
            key={hour}
            aria-hidden="true"
            className="top-(--top) pointer-events-none absolute inset-x-0 border-t border-border"
            style={
              // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
              { "--top": `${((hour - FIRST_HOUR) / (LAST_HOUR - FIRST_HOUR)) * 100}%` } as VarStyle
            }
          />
        ))}
        {days.map((day) => {
          const visible = events.filter((event) => event.day === day);
          return (
            <div
              key={day}
              role="group"
              aria-label={`Events on ${longDate(day)}`}
              onPointerDown={(pointer) => startCreate(pointer, day)}
              className="relative cursor-crosshair border-l border-border"
            >
              {day === selectedDay ? <span aria-hidden="true" className="pointer-events-none absolute inset-0 bg-muted/40" /> : null}
              {placeDay(visible).map((placed) => {
                const calendar = calendars.find((item) => item.id === placed.event.calendar) ?? calendars[0]!;
                return (
                  <EventBlock
                    key={placed.event.id}
                    placed={placed}
                    hue={calendar.hue}
                    calendarName={calendar.name}
                    helpId={helpId}
                    dragging={draggingId === placed.event.id}
                    onPointerDown={(pointer, mode) => startEvent(pointer, placed.event, mode)}
                    onNudge={(shiftDays, minutes, resize) => nudge(placed.event, shiftDays, minutes, resize)}
                  />
                );
              })}
              {draft && draft.day === day ? (
                <div
                  aria-hidden="true"
                  className={cn("top-(--top) h-(--height) pointer-events-none absolute inset-x-0.5 rounded-md border-2 border-dashed px-1.5 py-0.5 text-xs", HUE_BORDER[1])}
                  style={
                    // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
                    { "--top": `${((draft.start - FIRST_HOUR * 60) / SPAN) * 100}%`, "--height": `${((draft.end - draft.start) / SPAN) * 100}%` } as VarStyle
                  }
                >
                  <span className="tabular-nums text-muted-foreground">
                    {clock(draft.start)} to {clock(draft.end)}
                  </span>
                </div>
              ) : null}
              {day === TODAY ? (
                <span
                  aria-hidden="true"
                  className="top-(--top) pointer-events-none absolute inset-x-0 z-10 border-t-2 border-chart-5"
                  style={
                    // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
                    { "--top": `${((NOW - FIRST_HOUR * 60) / SPAN) * 100}%` } as VarStyle
                  }
                >
                  <span className="absolute -top-1.5 -left-1.5 size-2.5 rounded-full bg-chart-5" />
                </span>
              ) : null}
            </div>
          );
        })}
      </div>
    </div>
  );
}

