import { motion, useReducedMotion } from "motion/react";
import type { KeyboardEvent, PointerEvent } from "react";

import { cn } from "@/lib/utils";

import { HUE_BORDER, HUE_FILL, type Hue } from "../shared/people";
import { FIRST_HOUR, LAST_HOUR } from "./data";
import { clock, longDate, type Placed } from "./layout";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

const SPAN = (LAST_HOUR - FIRST_HOUR) * 60;

const NUDGE = new Map([
  ["ArrowUp", [0, -15]],
  ["ArrowDown", [0, 15]],
  ["ArrowLeft", [-1, 0]],
  ["ArrowRight", [1, 0]],
]);

/** Props for one timed event in a day column. */
export interface EventBlockProps {
  placed: Placed;
  hue: Hue;
  calendarName: string;
  /** The id of the line that explains the keyboard moves. */
  helpId: string;
  /** True while this event is being dragged, so it follows the pointer without a spring. */
  dragging: boolean;
  onPointerDown: (event: PointerEvent, mode: "move" | "resize") => void;
  /** Alt with an arrow moves the event; Shift and Alt with up or down changes its length. */
  onNudge: (days: number, minutes: number, resize: boolean) => void;
}

/**
 * One event in the hour grid: a tinted block with a coloured edge, placed
 * beside the events it overlaps. Drag it to move it, or drag its foot to
 * change its length. It glides to a new place with transforms only.
 */
export function EventBlock({ placed, hue, calendarName, helpId, dragging, onPointerDown, onNudge }: EventBlockProps) {
  const reduceMotion = useReducedMotion();
  const { event, lane, lanes } = placed;
  const top = ((Math.max(event.start, FIRST_HOUR * 60) - FIRST_HOUR * 60) / SPAN) * 100;
  const height = ((Math.min(event.end, LAST_HOUR * 60) - Math.max(event.start, FIRST_HOUR * 60)) / SPAN) * 100;
  const short = event.end - event.start <= 30;

  const onKeyDown = (key: KeyboardEvent) => {
    if (!key.altKey) return;
    const step = NUDGE.get(key.key);
    if (!step) return;
    key.preventDefault();
    key.stopPropagation();
    const [days = 0, minutes = 0] = step;
    onNudge(key.shiftKey ? 0 : days, minutes, key.shiftKey);
  };

  return (
    <motion.div
      layout={dragging || reduceMotion ? false : "position"}
      transition={{ type: "spring", stiffness: 420, damping: 40 }}
      className="top-(--top) h-(--height) left-(--left) w-(--width) absolute px-0.5"
      style={
        // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
        { "--top": `${top}%`, "--height": `${height}%`, "--left": `${(lane / lanes) * 100}%`, "--width": `${100 / lanes}%` } as VarStyle
      }
    >
      <div
        role="button"
        tabIndex={0}
        aria-label={`${event.title}, ${calendarName}, ${longDate(event.day)}, ${clock(event.start)} to ${clock(event.end)}`}
        aria-describedby={helpId}
        onPointerDown={(pointer) => onPointerDown(pointer, "move")}
        onKeyDown={onKeyDown}
        className={cn(
          "group relative isolate flex h-full cursor-grab touch-none flex-col overflow-hidden rounded-md border-l-2 px-1.5 py-0.5 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring",
          HUE_BORDER[hue],
          dragging && "cursor-grabbing shadow-lg",
        )}
      >
        <span aria-hidden="true" className={cn("absolute inset-0 -z-10 opacity-20 group-hover:opacity-30", HUE_FILL[hue])} />
        <span className={cn("truncate text-xs font-medium", short && "leading-tight")}>{event.title}</span>
        {short ? null : (
          <span className="truncate text-xs tabular-nums text-muted-foreground">
            {clock(event.start)} to {clock(event.end)}
          </span>
        )}
        <span
          aria-hidden="true"
          onPointerDown={(pointer) => {
            pointer.stopPropagation();
            onPointerDown(pointer, "resize");
          }}
          className="absolute inset-x-0 bottom-0 h-1.5 cursor-ns-resize"
        />
      </div>
    </motion.div>
  );
}

